//! Replays send configuration and label fixtures generated by the real web client.

use openchamber_native_core::send_config::{
    self, AgentColor, AgentEntry, AgentMode, AutoRouting, CatalogModel, CatalogProvider, FlatModel,
    FlatProvider, ModelChoice, Selection, SelectionDefaults, SyntaxPaletteEntry,
};
use serde::Deserialize;

const FIXTURE: &str = include_str!("fixtures/send_config.json");

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Fixture {
    selections: Vec<SelectionScenario>,
    grouping: Vec<GroupingScenario>,
    model_labels: Vec<ModelLabelScenario>,
    agent_labels: Vec<AgentLabelScenario>,
    colors: Vec<ColorScenario>,
}

#[derive(Clone, Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct FixtureModel {
    id: String,
    provider_model_id: Option<String>,
    name: Option<String>,
    #[serde(default)]
    variants: Vec<String>,
}

impl From<&FixtureModel> for CatalogModel {
    fn from(model: &FixtureModel) -> Self {
        Self {
            id: model.id.clone(),
            provider_model_id: model.provider_model_id.clone(),
            name: model.name.clone(),
            variants: model.variants.clone(),
            context_limit: None,
        }
    }
}

#[derive(Deserialize)]
struct FixtureProvider {
    id: String,
    name: Option<String>,
    models: Vec<FixtureModel>,
}

impl From<&FixtureProvider> for CatalogProvider {
    fn from(provider: &FixtureProvider) -> Self {
        Self {
            id: provider.id.clone(),
            name: provider.name.clone(),
            models: provider.models.iter().map(CatalogModel::from).collect(),
        }
    }
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct Choice {
    provider_id: String,
    model_id: String,
    variant: Option<String>,
}

impl From<&Choice> for ModelChoice {
    fn from(choice: &Choice) -> Self {
        Self {
            provider_id: choice.provider_id.clone(),
            model_id: choice.model_id.clone(),
            variant: choice.variant.clone(),
        }
    }
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct FixtureAgent {
    name: String,
    display_name: Option<String>,
    mode: Option<String>,
    #[serde(default)]
    hidden: bool,
    #[serde(default)]
    options_hidden: bool,
    model: Option<Choice>,
    color: Option<String>,
}

impl From<&FixtureAgent> for AgentEntry {
    fn from(agent: &FixtureAgent) -> Self {
        Self {
            name: agent.name.clone(),
            display_name: agent.display_name.clone(),
            mode: agent.mode.as_deref().map(|mode| match mode {
                "primary" => AgentMode::Primary,
                "subagent" => AgentMode::Subagent,
                "all" => AgentMode::All,
                other => panic!("unsupported fixture agent mode {other}"),
            }),
            hidden: agent.hidden || agent.options_hidden,
            model: agent.model.as_ref().map(ModelChoice::from),
            color: agent.color.clone(),
        }
    }
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Defaults {
    project_default_agent: Option<String>,
    project_default_model: Option<String>,
    project_default_variant: Option<String>,
    settings_default_agent: Option<String>,
    settings_default_model: Option<String>,
    settings_default_variant: Option<String>,
    opencode_default_agent: Option<String>,
    opencode_default_model: Option<String>,
    last_selected_model: Option<String>,
    #[serde(default)]
    hidden_models: Vec<(String, String)>,
    allow_fallback: bool,
    auto_routing: Option<String>,
}

impl From<&Defaults> for SelectionDefaults {
    fn from(defaults: &Defaults) -> Self {
        Self {
            project_default_agent: defaults.project_default_agent.clone(),
            project_default_model: defaults.project_default_model.clone(),
            project_default_variant: defaults.project_default_variant.clone(),
            settings_default_agent: defaults.settings_default_agent.clone(),
            settings_default_model: defaults.settings_default_model.clone(),
            settings_default_variant: defaults.settings_default_variant.clone(),
            opencode_default_agent: defaults.opencode_default_agent.clone(),
            opencode_default_model: defaults.opencode_default_model.clone(),
            last_selected_model: defaults.last_selected_model.clone(),
            hidden_models: defaults.hidden_models.clone(),
            allow_fallback: defaults.allow_fallback,
            auto_routing: match defaults.auto_routing.as_deref().unwrap_or("unknown") {
                "unknown" => AutoRouting::Unknown,
                "unavailable" => AutoRouting::Unavailable,
                "ready" => AutoRouting::Ready,
                "notReady" => AutoRouting::NotReady,
                other => panic!("unsupported fixture routing state {other}"),
            },
        }
    }
}

#[derive(Deserialize)]
struct SelectionInput {
    agents: Vec<FixtureAgent>,
    providers: Vec<FixtureProvider>,
    defaults: Defaults,
    #[serde(rename = "settingsLoaded")]
    settings_loaded: Option<bool>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct ExpectedSelection {
    agent_name: Option<String>,
    model: Option<Choice>,
}

#[derive(Deserialize)]
struct SelectionScenario {
    name: String,
    input: SelectionInput,
    expected: ExpectedSelection,
}

#[derive(Deserialize)]
struct GroupingProvider {
    id: String,
    name: Option<String>,
    enabled: bool,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct GroupingModel {
    #[serde(flatten)]
    model: FixtureModel,
    provider_id: String,
    enabled: bool,
}

#[derive(Deserialize)]
struct GroupingInput {
    providers: Vec<GroupingProvider>,
    models: Vec<GroupingModel>,
}

#[derive(Deserialize)]
struct GroupingScenario {
    name: String,
    input: GroupingInput,
    expected: Vec<FixtureProvider>,
}

#[derive(Deserialize)]
struct ModelLabelInput {
    providers: Vec<FixtureProvider>,
    choice: Choice,
}

#[derive(Deserialize)]
struct ModelLabelScenario {
    name: String,
    input: ModelLabelInput,
    expected: String,
}

#[derive(Deserialize)]
struct AgentLabelScenario {
    input: FixtureAgent,
    expected: String,
    hidden: bool,
}

#[derive(Deserialize)]
struct PaletteEntry {
    index: usize,
    colorful: bool,
}

#[derive(Deserialize)]
#[serde(tag = "kind", rename_all = "camelCase")]
enum ExpectedColor {
    Configured { value: String },
    Success,
    Syntax { index: usize, of: usize },
}

impl From<&ExpectedColor> for AgentColor {
    fn from(color: &ExpectedColor) -> Self {
        match color {
            ExpectedColor::Configured { value } => Self::Configured(value.clone()),
            ExpectedColor::Success => Self::Success,
            ExpectedColor::Syntax { index, of } => Self::Syntax {
                index: *index,
                of: *of,
            },
        }
    }
}

#[derive(Deserialize)]
struct ColorPick {
    name: Option<String>,
    color: ExpectedColor,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct ColorScenario {
    name: String,
    agents: Vec<FixtureAgent>,
    syntax_roles: usize,
    palette: Vec<PaletteEntry>,
    expected: Vec<ColorPick>,
}

#[test]
fn default_selection_matches_reference() {
    let fixture: Fixture =
        serde_json::from_str(FIXTURE).expect("send configuration fixture is valid JSON");
    assert!(
        fixture.selections.len() >= 55,
        "default cascade fixtures must retain their edge-case coverage"
    );
    for scenario in fixture.selections {
        let agents: Vec<AgentEntry> = scenario.input.agents.iter().map(AgentEntry::from).collect();
        let providers: Vec<CatalogProvider> = scenario
            .input
            .providers
            .iter()
            .map(CatalogProvider::from)
            .collect();
        let expected = Selection {
            agent_name: scenario.expected.agent_name,
            model: scenario.expected.model.as_ref().map(ModelChoice::from),
        };
        let mut defaults = SelectionDefaults::from(&scenario.input.defaults);
        if scenario.input.settings_loaded == Some(false)
            && defaults.auto_routing != AutoRouting::Ready
        {
            defaults.auto_routing = AutoRouting::Unknown;
        }
        assert_eq!(
            send_config::resolve_default_selection(&agents, &providers, &defaults),
            expected,
            "scenario `{}` diverged",
            scenario.name
        );
    }
}

#[test]
fn grouping_matches_reference() {
    let fixture: Fixture =
        serde_json::from_str(FIXTURE).expect("send configuration fixture is valid JSON");
    for scenario in fixture.grouping {
        let providers: Vec<FlatProvider> = scenario
            .input
            .providers
            .iter()
            .map(|provider| FlatProvider {
                id: provider.id.clone(),
                name: provider.name.clone(),
                enabled: provider.enabled,
            })
            .collect();
        let models: Vec<FlatModel> = scenario
            .input
            .models
            .iter()
            .map(|entry| FlatModel {
                id: entry.model.id.clone(),
                provider_id: entry.provider_id.clone(),
                provider_model_id: entry.model.provider_model_id.clone(),
                name: entry.model.name.clone(),
                variants: entry.model.variants.clone(),
                context_limit: None,
                enabled: entry.enabled,
            })
            .collect();
        let expected: Vec<CatalogProvider> = scenario
            .expected
            .iter()
            .map(CatalogProvider::from)
            .collect();
        assert_eq!(
            send_config::group_catalog(&providers, &models),
            expected,
            "scenario `{}` diverged",
            scenario.name
        );
    }
}

#[test]
fn composer_labels_match_reference() {
    let fixture: Fixture =
        serde_json::from_str(FIXTURE).expect("send configuration fixture is valid JSON");
    for scenario in fixture.model_labels {
        let providers: Vec<CatalogProvider> = scenario
            .input
            .providers
            .iter()
            .map(CatalogProvider::from)
            .collect();
        assert_eq!(
            send_config::model_label(&providers, &ModelChoice::from(&scenario.input.choice)),
            scenario.expected,
            "model label `{}` diverged",
            scenario.name
        );
    }
    for scenario in fixture.agent_labels {
        let agent = AgentEntry::from(&scenario.input);
        assert_eq!(
            send_config::agent_label(&agent),
            scenario.expected,
            "agent label `{}` diverged",
            agent.name
        );
        assert_eq!(
            agent.hidden, scenario.hidden,
            "hidden projection must match the web adapter"
        );
    }
    assert_eq!(
        send_config::agent_name_label("missing-agent"),
        "Missing-agent",
        "unknown agent IDs use capitalization"
    );
}

#[test]
fn agent_colors_match_reference_prepared_palettes() {
    let fixture: Fixture =
        serde_json::from_str(FIXTURE).expect("send configuration fixture is valid JSON");
    for scenario in fixture.colors {
        let agents: Vec<AgentEntry> = scenario.agents.iter().map(AgentEntry::from).collect();
        let palette: Vec<SyntaxPaletteEntry> = scenario
            .palette
            .iter()
            .map(|entry| SyntaxPaletteEntry {
                index: entry.index,
                colorful: entry.colorful,
            })
            .collect();
        for pick in scenario.expected {
            assert_eq!(
                send_config::agent_color_with_palette(
                    pick.name.as_deref(),
                    &agents,
                    &palette,
                    scenario.syntax_roles
                ),
                AgentColor::from(&pick.color),
                "color `{}` for {:?} diverged",
                scenario.name,
                pick.name
            );
        }
    }
    assert_eq!(
        send_config::agent_color(None, &[], 7),
        AgentColor::Success,
        "an absent agent uses success"
    );
    assert_eq!(
        send_config::agent_color(Some("build"), &[], 7),
        AgentColor::Success,
        "Build uses success"
    );
    assert_eq!(
        send_config::agent_color(Some("plan"), &[], 0),
        AgentColor::Success,
        "no syntax palette falls back safely"
    );
    assert_eq!(
        send_config::agent_color(Some("plan"), &[], 7),
        AgentColor::Syntax { index: 1, of: 7 },
        "an unknown agent hashes into the supplied palette"
    );
}
